175→// branchCheckpointResult contains the result of searching for a checkpoint on a branch.
176→type branchCheckpointResult struct {
177→	checkpointID      id.CheckpointID
178→	commitHash        string
179→	commitMessage     string
180→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
181→	newerCommitCount  int  // count of branch-only commits without checkpoints
182→}
183→
184→// findBranchCheckpoint finds the most recent commit with an Entire-Checkpoint trailer
185→// among commits that are unique to this branch (not reachable from the default branch).
186→// This handles the case where main has been merged into the feature branch.
187→func findBranchCheckpoint(repo *git.Repository, branchName string) (*branchCheckpointResult, error) {
188→	result := &branchCheckpointResult{}
189→
190→	// Get HEAD commit
191→	head, err := repo.Head()
192→	if err != nil {
193→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
194→	}
195→
196→	headCommit, err := repo.CommitObject(head.Hash())
197→	if err != nil {
198→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
199→	}
200→
201→	// First, check if HEAD itself has a checkpoint (most common case)
202→	if cpID, found := trailers.ParseCheckpoint(headCommit.Message); found {
203→		result.checkpointID = cpID
204→		result.commitHash = head.Hash().String()
205→		result.commitMessage = headCommit.Message
206→		result.newerCommitsExist = false
207→		return result, nil
208→	}
209→
210→	// HEAD doesn't have a checkpoint - find branch-only commits
211→	// Get the default branch name
212→	defaultBranch := getDefaultBranchFromRemote(repo)
213→	if defaultBranch == "" {
214→		// Fallback: try common names
215→		for _, name := range []string{"main", "master"} {
216→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
217→				defaultBranch = name
218→				break
219→			}
220→		}
221→	}
222→
223→	// If we can't find a default branch, or we're on it, just walk all commits
224→	if defaultBranch == "" || defaultBranch == branchName {
225→		return findCheckpointInHistory(headCommit, nil), nil
226→	}
227→
228→	// Get the default branch reference
229→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
230→	if err != nil {
231→		// Default branch doesn't exist locally, fall back to walking all commits
232→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
233→	}
234→
235→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
236→	if err != nil {
237→		// Can't get default commit, fall back to walking all commits
238→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
239→	}
240→
241→	// Find merge base
242→	mergeBase, err := headCommit.MergeBase(defaultCommit)
243→	if err != nil || len(mergeBase) == 0 {
244→		// No common ancestor, fall back to walking all commits
245→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
246→	}
247→
248→	// Walk from HEAD to merge base, looking for checkpoint
249→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
250→}
251→
252→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
253→// If stopAt is provided, stops when reaching that commit (exclusive).
254→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
255→// It distinguishes between merge commits (bringing in other branches) and regular commits
256→// (actual branch work) to avoid false warnings after merging main.
257→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointResult {
258→	result := &branchCheckpointResult{}
259→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
260→	const maxCommits = 100 // Limit search depth
261→	totalChecked := 0
262→
263→	current := start
264→	for current != nil && totalChecked < maxCommits {
265→		// Stop if we've reached the boundary
266→		if stopAt != nil && current.Hash == *stopAt {
267→			break
268→		}
269→
270→		// Check for checkpoint trailer
271→		if cpID, found := trailers.ParseCheckpoint(current.Message); found {
272→			result.checkpointID = cpID
273→			result.commitHash = current.Hash.String()
274→			result.commitMessage = current.Message
275→			// Only warn about branch work commits, not merge commits
276→			result.newerCommitsExist = branchWorkCommits > 0
277→			result.newerCommitCount = branchWorkCommits
278→			return result
279→		}
280→
281→		// Only count regular commits (not merge commits) as "branch work"
282→		if current.NumParents() <= 1 {
283→			branchWorkCommits++
284→		}
285→
286→		totalChecked++
287→
288→		// Move to parent (first parent for merge commits - follows the main line)
289→		if current.NumParents() == 0 {
290→			break
291→		}
292→		parent, err := current.Parent(0)
293→		if err != nil {
294→			// Can't get parent, treat as end of history
295→			break
296→		}
297→		current = parent
298→	}
299→
300→	// No checkpoint found
301→	return result
302→}
