304→// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
305→func promptResumeFromOlderCheckpoint() (bool, error) {
306→	var confirmed bool
307→
308→	form := NewAccessibleForm(
309→		huh.NewGroup(
310→			huh.NewConfirm().
311→				Title("Resume from this older checkpoint?").
312→				Value(&confirmed),
313→		),
314→	)
315→
316→	if err := form.Run(); err != nil {
317→		if errors.Is(err, huh.ErrUserAborted) {
318→			return false, nil
319→		}
320→		return false, fmt.Errorf("failed to get confirmation: %w", err)
321→	}
322→
323→	return confirmed, nil
324→}
