326→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
327→// and automatically fetches it if available.
328→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
329→	// Try to get remote metadata branch tree
330→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
331→	if err != nil {
332→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
333→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
334→		return nil //nolint:nilerr // Informational message, not a fatal error
335→	}
336→
337→	// Check if the checkpoint exists on the remote
338→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
339→	if err != nil {
340→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
341→		return nil //nolint:nilerr // Informational message, not a fatal error
342→	}
343→
344→	// Metadata exists on remote but not locally - fetch it automatically
345→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
346→	if err := FetchMetadataBranch(ctx); err != nil {
347→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
348→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
349→		return NewSilentError(errors.New("failed to fetch metadata"))
350→	}
351→
352→	// Now resume the session with the fetched metadata
353→	return resumeSession(ctx, metadata.SessionID, checkpointID, false)
354→}
