356→// resumeSession restores and displays the resume command for a specific session.
357→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
358→// If force is false, prompts for confirmation when local logs have newer timestamps.
359→func resumeSession(ctx context.Context, sessionID string, checkpointID id.CheckpointID, force bool) error {
360→	// Read checkpoint metadata first to get agent type (matching rewind pattern)
361→	repo, err := openRepository(ctx)
362→	if err != nil {
363→		return fmt.Errorf("failed to open repository: %w", err)
364→	}
365→
366→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
367→	if err != nil {
368→		return fmt.Errorf("failed to get metadata branch: %w", err)
369→	}
370→
371→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
372→	if err != nil {
373→		return fmt.Errorf("failed to read checkpoint metadata: %w", err)
374→	}
375→
376→	// Resolve agent from checkpoint metadata (same as rewind)
377→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
378→	if err != nil {
379→		return fmt.Errorf("failed to resolve agent: %w", err)
380→	}
381→
382→	// Initialize logging context with agent
383→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
384→
385→	logging.Debug(logCtx, "resume session started",
386→		slog.String("checkpoint_id", checkpointID.String()),
387→		slog.String("session_id", sessionID),
388→	)
389→
390→	// Get worktree root for session directory lookup
391→	repoRoot, err := paths.WorktreeRoot(ctx)
392→	if err != nil {
393→		return fmt.Errorf("failed to get worktree root: %w", err)
394→	}
395→
396→	sessionDir, err := ag.GetSessionDir(repoRoot)
397→	if err != nil {
398→		return fmt.Errorf("failed to determine session directory: %w", err)
399→	}
400→
401→	// Create directory if it doesn't exist
402→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
403→		return fmt.Errorf("failed to create session directory: %w", err)
404→	}
405→
406→	// Get strategy and restore sessions using full checkpoint data
407→	strat := GetStrategy(ctx)
408→
409→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
410→	// Create a logs-only rewind point with Agent populated (same as rewind)
411→	point := strategy.RewindPoint{
412→		IsLogsOnly:   true,
413→		CheckpointID: checkpointID,
414→		Agent:        metadata.Agent,
415→	}
416→
417→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
418→	if restoreErr != nil || len(sessions) == 0 {
419→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
420→		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
421→	}
422→
423→	// Sort sessions by CreatedAt so the most recent is last (for display).
424→	// This fixes ordering when subdirectory index doesn't reflect activity order.
425→	sort.Slice(sessions, func(i, j int) bool {
426→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
427→	})
428→
429→	logging.Debug(logCtx, "resume session completed",
430→		slog.String("checkpoint_id", checkpointID.String()),
431→		slog.Int("session_count", len(sessions)),
432→	)
433→
434→	// Print per-session resume commands using returned sessions
435→	if len(sessions) > 1 {
436→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
437→	} else if len(sessions) == 1 {
438→		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
439→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
440→	}
441→	for i, sess := range sessions {
442→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
443→		if err != nil {
444→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
445→		}
446→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
447→
448→		if len(sessions) > 1 {
449→			if i == len(sessions)-1 {
450→				if sess.Prompt != "" {
451→					fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
452→				} else {
453→					fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
454→				}
455→			} else {
456→				if sess.Prompt != "" {
457→					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
458→				} else {
459→					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
460→				}
461→			}
462→		} else {
463→			if sess.Prompt != "" {
464→				fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
465→			} else {
466→				fmt.Fprintf(os.Stderr, "  %s\n", cmd)
467→			}
468→		}
469→	}
470→
471→	return nil
472→}
