474→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
475→// Always overwrites existing session logs to ensure consistency with checkpoint state.
476→// If force is false, prompts for confirmation when local log has newer timestamps.
477→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
478→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
479→	if err != nil {
480→		return fmt.Errorf("failed to resolve transcript path: %w", err)
481→	}
482→
483→	if checkpointID.IsEmpty() {
484→		logging.Debug(ctx, "resume session: empty checkpoint ID",
485→			slog.String("checkpoint_id", checkpointID.String()),
486→		)
487→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
488→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
489→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
490→		return nil
491→	}
492→
493→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
494→	if err != nil {
495→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
496→			logging.Debug(ctx, "resume session completed (no metadata)",
497→				slog.String("checkpoint_id", checkpointID.String()),
498→				slog.String("session_id", sessionID),
499→			)
500→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
501→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
502→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
503→			return nil
504→		}
505→		logging.Error(ctx, "resume session failed",
506→			slog.String("checkpoint_id", checkpointID.String()),
507→			slog.String("session_id", sessionID),
508→			slog.String("error", err.Error()),
509→		)
510→		return fmt.Errorf("failed to get session log: %w", err)
511→	}
512→
513→	// Check if local file has newer timestamps than checkpoint
514→	if !force {
515→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
516→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
517→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
518→
519→		if status == strategy.StatusLocalNewer {
520→			sessions := []strategy.SessionRestoreInfo{{
521→				SessionID:      sessionID,
522→				Status:         status,
523→				LocalTime:      localTime,
524→				CheckpointTime: checkpointTime,
525→			}}
526→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
527→			if promptErr != nil {
528→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
529→			}
530→			if !shouldOverwrite {
531→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
532→				return nil
533→			}
534→		}
535→	}
536→
537→	// Ensure parent directory exists
538→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
539→		return fmt.Errorf("failed to create session directory: %w", err)
540→	}
541→
542→	agentSession := &agent.AgentSession{
543→		SessionID:  sessionID,
544→		AgentName:  ag.Name(),
545→		RepoPath:   repoRoot,
546→		SessionRef: sessionLogPath,
547→		NativeData: logContent,
548→	}
549→
550→	// Write the session using the agent's WriteSession method
551→	if err := ag.WriteSession(ctx, agentSession); err != nil {
552→		logging.Error(ctx, "resume session failed during write",
553→			slog.String("checkpoint_id", checkpointID.String()),
554→			slog.String("session_id", sessionID),
555→			slog.String("error", err.Error()),
556→		)
557→		return fmt.Errorf("failed to write session: %w", err)
558→	}
559→
560→	logging.Debug(ctx, "resume session completed",
561→		slog.String("checkpoint_id", checkpointID.String()),
562→		slog.String("session_id", sessionID),
563→	)
564→
565→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
566→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
