272→func createCheckpointOnMetadataBranch(t *testing.T, repo *git.Repository, sessionID string) id.CheckpointID {
273→	t.Helper()
274→
275→	checkpointID := id.MustCheckpointID("abc123def456") // Fixed ID for testing
276→
277→	// Get existing metadata branch or create it
278→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
279→		t.Fatalf("Failed to ensure metadata branch: %v", err)
280→	}
281→
282→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
283→	ref, err := repo.Reference(refName, true)
284→	if err != nil {
285→		t.Fatalf("Failed to get metadata branch ref: %v", err)
286→	}
287→
288→	parentCommit, err := repo.CommitObject(ref.Hash())
289→	if err != nil {
290→		t.Fatalf("Failed to get parent commit: %v", err)
291→	}
292→
293→	// Create metadata content
294→	metadataJSON := fmt.Sprintf(`{
295→  "checkpoint_id": %q,
296→  "session_id": %q,
297→  "created_at": "2025-01-01T00:00:00Z"
298→}`, checkpointID.String(), sessionID)
299→
300→	// Create blob for metadata
301→	blob := repo.Storer.NewEncodedObject()
302→	blob.SetType(plumbing.BlobObject)
303→	writer, err := blob.Writer()
304→	if err != nil {
305→		t.Fatalf("Failed to create blob writer: %v", err)
306→	}
307→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
308→		t.Fatalf("Failed to write blob: %v", err)
309→	}
310→	if err := writer.Close(); err != nil {
311→		t.Fatalf("Failed to close writer: %v", err)
312→	}
313→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
314→	if err != nil {
315→		t.Fatalf("Failed to store blob: %v", err)
316→	}
317→
318→	// Create session log blob
319→	logBlob := repo.Storer.NewEncodedObject()
320→	logBlob.SetType(plumbing.BlobObject)
321→	logWriter, err := logBlob.Writer()
322→	if err != nil {
323→		t.Fatalf("Failed to create log blob writer: %v", err)
324→	}
325→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
326→		t.Fatalf("Failed to write log blob: %v", err)
327→	}
328→	if err := logWriter.Close(); err != nil {
329→		t.Fatalf("Failed to close log writer: %v", err)
330→	}
331→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
332→	if err != nil {
333→		t.Fatalf("Failed to store log blob: %v", err)
334→	}
335→
336→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
337→	shardedPath := checkpointID.Path()
338→	checkpointIDStr := checkpointID.String()
339→
340→	// Create checkpoint tree with metadata and transcript files
341→	// Entries must be sorted alphabetically
342→	checkpointTree := object.Tree{
343→		Entries: []object.TreeEntry{
344→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
345→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
346→		},
347→	}
348→	checkpointTreeObj := repo.Storer.NewEncodedObject()
349→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
350→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
