185→func resumeMultipleCheckpoints(ctx context.Context, repo *git.Repository, checkpointIDs []id.CheckpointID, force bool) error {
186→	logCtx := logging.WithComponent(ctx, "resume")
187→
188→	// Get metadata branch tree (try local first, then remote)
189→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
190→	if err != nil {
191→		// Try fetching from remote
192→		logging.Debug(logCtx, "metadata branch not available locally, trying remote")
193→		if fetchErr := FetchMetadataBranch(ctx); fetchErr != nil {
194→			// If fetch also fails, try remote tree directly
195→			remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
196→			if remoteErr != nil {
197→				fmt.Fprintf(os.Stderr, "Checkpoint metadata not available locally or on remote\n")
198→				return nil //nolint:nilerr // Informational message, not a fatal error
199→			}
200→			metadataTree = remoteTree
201→		} else {
202→			metadataTree, err = strategy.GetMetadataBranchTree(repo)
203→			if err != nil {
204→				fmt.Fprintf(os.Stderr, "Checkpoint metadata not available after fetch\n")
205→				return nil //nolint:nilerr // Informational message, not a fatal error
206→			}
207→		}
208→	}
209→
210→	strat := GetStrategy(ctx)
211→	repoRoot, err := paths.WorktreeRoot(ctx)
212→	if err != nil {
213→		return fmt.Errorf("failed to get worktree root: %w", err)
214→	}
215→
216→	var allSessions []strategy.RestoredSession
217→
218→	for _, cpID := range checkpointIDs {
219→		metadata, metaErr := strategy.ReadCheckpointMetadata(metadataTree, cpID.Path())
220→		if metaErr != nil {
221→			logging.Debug(logCtx, "skipping checkpoint without metadata",
222→				slog.String("checkpoint_id", cpID.String()),
223→				slog.String("error", metaErr.Error()),
224→			)
225→			continue
226→		}
227→
228→		ag, agErr := strategy.ResolveAgentForRewind(metadata.Agent)
229→		if agErr != nil {
230→			logging.Debug(logCtx, "skipping checkpoint with unknown agent",
231→				slog.String("checkpoint_id", cpID.String()),
232→				slog.String("error", agErr.Error()),
233→			)
234→			continue
235→		}
236→
237→		sessionDir, dirErr := ag.GetSessionDir(repoRoot)
238→		if dirErr != nil {
239→			logging.Debug(logCtx, "skipping checkpoint: cannot determine session dir",
240→				slog.String("checkpoint_id", cpID.String()),
241→				slog.String("error", dirErr.Error()),
242→			)
243→			continue
244→		}
245→		if mkErr := os.MkdirAll(sessionDir, 0o700); mkErr != nil {
246→			logging.Debug(logCtx, "skipping checkpoint: cannot create session dir",
247→				slog.String("checkpoint_id", cpID.String()),
248→				slog.String("error", mkErr.Error()),
249→			)
250→			continue
251→		}
252→
253→		point := strategy.RewindPoint{
254→			IsLogsOnly:   true,
255→			CheckpointID: cpID,
256→			Agent:        metadata.Agent,
257→		}
258→
259→		sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
260→		if restoreErr != nil || len(sessions) == 0 {
261→			logging.Debug(logCtx, "skipping checkpoint: restore failed",
262→				slog.String("checkpoint_id", cpID.String()),
263→			)
264→			continue
265→		}
266→
267→		allSessions = append(allSessions, sessions...)
268→	}
269→
270→	if len(allSessions) == 0 {
271→		fmt.Fprintf(os.Stderr, "No session metadata found for checkpoints in this commit\n")
272→		return nil
273→	}
274→
275→	// Sort by CreatedAt (same as resumeSession)
276→	sort.Slice(allSessions, func(i, j int) bool {
277→		return allSessions[i].CreatedAt.Before(allSessions[j].CreatedAt)
278→	})
279→
280→	logging.Debug(logCtx, "resume multiple checkpoints completed",
281→		slog.Int("checkpoint_count", len(checkpointIDs)),
282→		slog.Int("session_count", len(allSessions)),
283→	)
284→
285→	// Display resume commands (same format as resumeSession)
286→	if len(allSessions) > 1 {
287→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(allSessions))
288→	} else {
289→		fmt.Fprintf(os.Stderr, "Session: %s\n", allSessions[0].SessionID)
290→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
291→	}
292→	for i, sess := range allSessions {
293→		sessionAgent, agErr := strategy.ResolveAgentForRewind(sess.Agent)
294→		if agErr != nil {
295→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, agErr)
296→		}
297→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
298→
299→		if len(allSessions) > 1 {
300→			if i == len(allSessions)-1 {
301→				if sess.Prompt != "" {
302→					fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
303→				} else {
304→					fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
305→				}
306→			} else {
307→				if sess.Prompt != "" {
308→					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
309→				} else {
310→					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
311→				}
312→			}
313→		} else {
314→			if sess.Prompt != "" {
315→				fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
316→			} else {
317→				fmt.Fprintf(os.Stderr, "  %s\n", cmd)
318→			}
319→		}
320→	}
321→
322→	return nil
323→}
