123→func resumeFromCurrentBranch(ctx context.Context, branchName string, force bool) error {
124→	repo, err := openRepository(ctx)
125→	if err != nil {
126→		return fmt.Errorf("not a git repository: %w", err)
127→	}
128→
129→	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
130→	result, err := findBranchCheckpoint(repo, branchName)
131→	if err != nil {
132→		return err
133→	}
134→	if len(result.checkpointIDs) == 0 {
135→		fmt.Fprintf(os.Stderr, "No Entire checkpoint found on branch '%s'\n", branchName)
136→		return nil
137→	}
138→
139→	// If there are newer commits without checkpoints, ask for confirmation.
140→	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
141→	if result.newerCommitsExist && !force {
142→		fmt.Fprintf(os.Stderr, "Found checkpoint in an older commit.\n")
143→		fmt.Fprintf(os.Stderr, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
144→		fmt.Fprintf(os.Stderr, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))
145→
146→		shouldResume, err := promptResumeFromOlderCheckpoint()
147→		if err != nil {
148→			return err
149→		}
150→		if !shouldResume {
151→			fmt.Fprintf(os.Stderr, "Resume cancelled.\n")
152→			return nil
153→		}
154→	}
155→
156→	// Multiple checkpoints (squash merge): restore all sessions
157→	if len(result.checkpointIDs) > 1 {
158→		return resumeMultipleCheckpoints(ctx, repo, result.checkpointIDs, force)
159→	}
160→
161→	// Single checkpoint: existing behavior (unchanged)
162→	checkpointID := result.checkpointIDs[0]
163→
164→	// Get metadata branch tree for lookups
165→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
166→	if err != nil {
167→		// No local metadata branch, check if remote has it
168→		return checkRemoteMetadata(ctx, repo, checkpointID)
169→	}
170→
171→	// Look up metadata from sharded path
172→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
173→	if err != nil {
174→		// Checkpoint exists in commit but no local metadata - check remote
175→		return checkRemoteMetadata(ctx, repo, checkpointID)
176→	}
177→
178→	return resumeSession(ctx, metadata.SessionID, checkpointID, force)
179→}
