326→type branchCheckpointResult struct {
327→	checkpointIDs     []id.CheckpointID
328→	commitHash        string
329→	commitMessage     string
330→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
331→	newerCommitCount  int  // count of branch-only commits without checkpoints
332→}
