334→// findBranchCheckpoint finds the most recent commit with an Entire-Checkpoint trailer
335→// among commits that are unique to this branch (not reachable from the default branch).
336→// This handles the case where main has been merged into the feature branch.
337→func findBranchCheckpoint(repo *git.Repository, branchName string) (*branchCheckpointResult, error) {
338→	result := &branchCheckpointResult{}
339→
340→	// Get HEAD commit
341→	head, err := repo.Head()
342→	if err != nil {
343→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
344→	}
345→
346→	headCommit, err := repo.CommitObject(head.Hash())
347→	if err != nil {
348→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
349→	}
350→
351→	// First, check if HEAD itself has a checkpoint (most common case)
352→	if cpIDs := trailers.ParseAllCheckpoints(headCommit.Message); len(cpIDs) > 0 {
353→		result.checkpointIDs = cpIDs
354→		result.commitHash = head.Hash().String()
355→		result.commitMessage = headCommit.Message
356→		result.newerCommitsExist = false
357→		return result, nil
358→	}
359→
360→	// HEAD doesn't have a checkpoint - find branch-only commits
361→	// Get the default branch name
362→	defaultBranch := getDefaultBranchFromRemote(repo)
363→	if defaultBranch == "" {
364→		// Fallback: try common names
365→		for _, name := range []string{"main", "master"} {
366→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
367→				defaultBranch = name
368→				break
369→			}
370→		}
371→	}
372→
373→	// If we can't find a default branch, or we're on it, just walk all commits
374→	if defaultBranch == "" || defaultBranch == branchName {
375→		return findCheckpointInHistory(headCommit, nil), nil
376→	}
377→
378→	// Get the default branch reference
379→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
380→	if err != nil {
381→		// Default branch doesn't exist locally, fall back to walking all commits
382→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
383→	}
384→
385→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
386→	if err != nil {
387→		// Can't get default commit, fall back to walking all commits
388→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
389→	}
390→
391→	// Find merge base
392→	mergeBase, err := headCommit.MergeBase(defaultCommit)
393→	if err != nil || len(mergeBase) == 0 {
394→		// No common ancestor, fall back to walking all commits
395→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
396→	}
397→
398→	// Walk from HEAD to merge base, looking for checkpoint
399→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
400→}
