402→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
403→// If stopAt is provided, stops when reaching that commit (exclusive).
404→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
405→// It distinguishes between merge commits (bringing in other branches) and regular commits
406→// (actual branch work) to avoid false warnings after merging main.
407→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointResult {
408→	result := &branchCheckpointResult{}
409→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
410→	const maxCommits = 100 // Limit search depth
411→	totalChecked := 0
412→
413→	current := start
414→	for current != nil && totalChecked < maxCommits {
415→		// Stop if we've reached the boundary
416→		if stopAt != nil && current.Hash == *stopAt {
417→			break
418→		}
419→
420→		// Check for checkpoint trailer
421→		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
422→			result.checkpointIDs = cpIDs
423→			result.commitHash = current.Hash.String()
424→			result.commitMessage = current.Message
425→			// Only warn about branch work commits, not merge commits
426→			result.newerCommitsExist = branchWorkCommits > 0
427→			result.newerCommitCount = branchWorkCommits
428→			return result
429→		}
430→
431→		// Only count regular commits (not merge commits) as "branch work"
432→		if current.NumParents() <= 1 {
433→			branchWorkCommits++
434→		}
435→
436→		totalChecked++
437→
438→		// Move to parent (first parent for merge commits - follows the main line)
439→		if current.NumParents() == 0 {
440→			break
441→		}
