476→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
477→// and automatically fetches it if available.
478→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
479→	// Try to get remote metadata branch tree
480→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
481→	if err != nil {
482→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
483→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
484→		return nil //nolint:nilerr // Informational message, not a fatal error
485→	}
486→
487→	// Check if the checkpoint exists on the remote
488→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
489→	if err != nil {
490→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
491→		return nil //nolint:nilerr // Informational message, not a fatal error
492→	}
493→
494→	// Metadata exists on remote but not locally - fetch it automatically
495→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
496→	if err := FetchMetadataBranch(ctx); err != nil {
497→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
498→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
499→		return NewSilentError(errors.New("failed to fetch metadata"))
