506→// resumeSession restores and displays the resume command for a specific session.
507→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
508→// If force is false, prompts for confirmation when local logs have newer timestamps.
509→func resumeSession(ctx context.Context, sessionID string, checkpointID id.CheckpointID, force bool) error {
510→	// Read checkpoint metadata first to get agent type (matching rewind pattern)
511→	repo, err := openRepository(ctx)
512→	if err != nil {
513→		return fmt.Errorf("failed to open repository: %w", err)
514→	}
515→
516→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
517→	if err != nil {
518→		return fmt.Errorf("failed to get metadata branch: %w", err)
519→	}
520→
521→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
522→	if err != nil {
523→		return fmt.Errorf("failed to read checkpoint metadata: %w", err)
524→	}
525→
526→	// Resolve agent from checkpoint metadata (same as rewind)
527→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
528→	if err != nil {
529→		return fmt.Errorf("failed to resolve agent: %w", err)
530→	}
531→
532→	// Initialize logging context with agent
533→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
534→
535→	logging.Debug(logCtx, "resume session started",
536→		slog.String("checkpoint_id", checkpointID.String()),
537→		slog.String("session_id", sessionID),
538→	)
539→
540→	// Get worktree root for session directory lookup
541→	repoRoot, err := paths.WorktreeRoot(ctx)
542→	if err != nil {
543→		return fmt.Errorf("failed to get worktree root: %w", err)
544→	}
545→
546→	sessionDir, err := ag.GetSessionDir(repoRoot)
547→	if err != nil {
548→		return fmt.Errorf("failed to determine session directory: %w", err)
549→	}
550→
551→	// Create directory if it doesn't exist
552→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
553→		return fmt.Errorf("failed to create session directory: %w", err)
554→	}
555→
556→	// Get strategy and restore sessions using full checkpoint data
557→	strat := GetStrategy(ctx)
558→
559→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
560→	// Create a logs-only rewind point with Agent populated (same as rewind)
561→	point := strategy.RewindPoint{
562→		IsLogsOnly:   true,
563→		CheckpointID: checkpointID,
564→		Agent:        metadata.Agent,
565→	}
566→
567→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
568→	if restoreErr != nil || len(sessions) == 0 {
569→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
570→		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
571→	}
572→
573→	// Sort sessions by CreatedAt so the most recent is last (for display).
574→	// This fixes ordering when subdirectory index doesn't reflect activity order.
575→	sort.Slice(sessions, func(i, j int) bool {
576→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
577→	})
578→
579→	logging.Debug(logCtx, "resume session completed",
580→		slog.String("checkpoint_id", checkpointID.String()),
581→		slog.Int("session_count", len(sessions)),
582→	)
583→
584→	// Print per-session resume commands using returned sessions
585→	if len(sessions) > 1 {
586→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
587→	} else if len(sessions) == 1 {
588→		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
589→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
590→	}
591→	for i, sess := range sessions {
592→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
593→		if err != nil {
594→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
595→		}
596→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
597→
598→		if len(sessions) > 1 {
599→			if i == len(sessions)-1 {
600→				if sess.Prompt != "" {
601→					fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
602→				} else {
603→					fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
604→				}
605→			} else {
606→				if sess.Prompt != "" {
607→					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
608→				} else {
609→					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
610→				}
611→			}
612→		} else {
613→			if sess.Prompt != "" {
614→				fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
615→			} else {
616→				fmt.Fprintf(os.Stderr, "  %s\n", cmd)
617→			}
618→		}
619→	}
620→
621→	return nil
622→}
