624→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
625→// Always overwrites existing session logs to ensure consistency with checkpoint state.
626→// If force is false, prompts for confirmation when local log has newer timestamps.
627→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
628→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
629→	if err != nil {
630→		return fmt.Errorf("failed to resolve transcript path: %w", err)
631→	}
632→
633→	if checkpointID.IsEmpty() {
634→		logging.Debug(ctx, "resume session: empty checkpoint ID",
635→			slog.String("checkpoint_id", checkpointID.String()),
636→		)
637→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
638→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
639→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
640→		return nil
641→	}
642→
643→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
644→	if err != nil {
645→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
646→			logging.Debug(ctx, "resume session completed (no metadata)",
647→				slog.String("checkpoint_id", checkpointID.String()),
648→				slog.String("session_id", sessionID),
649→			)
650→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
651→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
652→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
653→			return nil
654→		}
655→		logging.Error(ctx, "resume session failed",
656→			slog.String("checkpoint_id", checkpointID.String()),
657→			slog.String("session_id", sessionID),
658→			slog.String("error", err.Error()),
659→		)
660→		return fmt.Errorf("failed to get session log: %w", err)
661→	}
662→
663→	// Check if local file has newer timestamps than checkpoint
664→	if !force {
665→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
666→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
667→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
668→
669→		if status == strategy.StatusLocalNewer {
670→			sessions := []strategy.SessionRestoreInfo{{
671→				SessionID:      sessionID,
672→				Status:         status,
673→				LocalTime:      localTime,
674→				CheckpointTime: checkpointTime,
675→			}}
676→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
677→			if promptErr != nil {
678→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
679→			}
680→			if !shouldOverwrite {
681→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
682→				return nil
683→			}
684→		}
685→	}
686→
687→	// Ensure parent directory exists
688→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
689→		return fmt.Errorf("failed to create session directory: %w", err)
690→	}
691→
692→	agentSession := &agent.AgentSession{
693→		SessionID:  sessionID,
694→		AgentName:  ag.Name(),
695→		RepoPath:   repoRoot,
696→		SessionRef: sessionLogPath,
697→		NativeData: logContent,
698→	}
699→
700→	// Write the session using the agent's WriteSession method
701→	if err := ag.WriteSession(ctx, agentSession); err != nil {
702→		logging.Error(ctx, "resume session failed during write",
703→			slog.String("checkpoint_id", checkpointID.String()),
704→			slog.String("session_id", sessionID),
705→			slog.String("error", err.Error()),
706→		)
707→		return fmt.Errorf("failed to write session: %w", err)
708→	}
709→
710→	logging.Debug(ctx, "resume session completed",
711→		slog.String("checkpoint_id", checkpointID.String()),
712→		slog.String("session_id", sessionID),
713→	)
714→
715→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
716→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
717→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
718→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
719→
720→	return nil
721→}
